import java.nio.file.*;import java.sql.*;import java.util.*;
public class CatalogSeedTest {
 @SuppressWarnings("unchecked") public static void main(String[] args)throws Exception{
  Path directory=Files.createTempDirectory(Path.of(".local/catalog-seeding-20261028"),"ledger-test-");Path ledgerFile=directory.resolve("ledger.json");
  CatalogSeed.saveNewReport(ledgerFile,"prepared");boolean collision=false;try{CatalogSeed.saveNewReport(ledgerFile,"other");}catch(FileAlreadyExistsException e){collision=true;}
  check(collision&&"prepared".equals(Files.readString(ledgerFile)),"ledger must not be overwritten by competing importer");
  CatalogSeed.replaceReport(ledgerFile,"committed");check("committed".equals(Files.readString(ledgerFile)),"final ledger must replace atomically");
  var json=new com.fasterxml.jackson.databind.ObjectMapper();var m=json.readValue(Files.readString(Path.of(args[0])),Map.class);
  try(var c=DriverManager.getConnection("jdbc:h2:mem:catalog_seed_test;MODE=MySQL;DB_CLOSE_DELAY=-1","sa","")){
   var s=c.createStatement();
   s.execute("create table stores(id bigint primary key,slug varchar(150) unique,status varchar(40))");
   s.execute("create table categories(id bigint primary key,slug varchar(150) unique,is_active boolean)");
   s.execute("create table toppings(id bigint generated by default as identity primary key,name varchar(100),price decimal(14,2),is_active boolean,created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp)");
   s.execute("create table products(id bigint generated by default as identity primary key,store_id bigint references stores(id),category_id bigint references categories(id),name varchar(150),slug varchar(150) unique,catalog_key varchar(150),description varchar(4000),base_price decimal(14,2) default 0,is_active boolean default true,is_available boolean default false,is_featured boolean default false,image_url varchar(1000),image_public_id varchar(255),version bigint default 0,created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp)");
   s.execute("create table product_variants(id bigint generated by default as identity primary key,product_id bigint references products(id),size_name varchar(5),extra_price decimal(14,2),is_active boolean,stock_quantity int,version bigint default 0,created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp,unique(product_id,size_name))");
   s.execute("create table product_toppings(id bigint generated by default as identity primary key,product_id bigint references products(id),topping_id bigint references toppings(id),unique(product_id,topping_id))");
   s.execute("create table store_toppings(id bigint generated by default as identity primary key,store_id bigint references stores(id),topping_id bigint references toppings(id),is_available boolean,created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp,unique(store_id,topping_id))");
   // Only public catalog prerequisite copies. No accounts, orders or interactions are created even in this fixture.
   for(var x:(List<Map<String,Object>>)m.get("requirements")){
    String table=x.get("table").toString();var row=new LinkedHashMap<String,Object>((Map<String,Object>)x.get("expected"));row.put("id",x.get("id"));
    if(table.equals("products")){row.put("slug","existing-"+x.get("id"));}
    insert(c,table,row);
   }
   // Avoid generated-key collisions with prerequisite snapshots without resetting any sequence.
   for(String table:List.of("products","toppings"))for(int n=0;n<100;n++){
    var keys=c.prepareStatement(table.equals("products")?"insert into products(store_id,category_id,name,slug) values(1,1,'Fixture allocation',?)":"insert into toppings(name,price,is_active) values(?,0,false)",Statement.RETURN_GENERATED_KEYS);keys.setString(1,"fixture-allocation-"+n);keys.executeUpdate();
   }
   c.setAutoCommit(false);var save=c.setSavepoint();
   var removable=CatalogSeed.seed(c,m,true);removable.put("format","catalog-only-v1");removable.put("status","committed");removable.put("mode","apply");
   removable=json.readValue(json.writeValueAsString(removable),Map.class);
   var prepared=new LinkedHashMap<String,Object>(removable);prepared.put("status","prepared");check("committed".equals(CatalogSeed.reconcile(c,prepared).get("status")),"prepared ledger with matching rows must be recoverable");
   var firstProduct=((List<Map<String,Object>>)removable.get("created")).stream().filter(e->"products".equals(e.get("table"))).findFirst().orElseThrow();
   long productId=((Number)firstProduct.get("id")).longValue();write(c,"update products set base_price=base_price+1 where id=?",productId);
   boolean edited=false;try{CatalogSeed.rollback(c,removable,true);}catch(IllegalStateException e){edited=true;}check(edited,"edited row must prevent every delete");
   for(var e:(List<Map<String,Object>>)removable.get("created"))check(!CatalogSeed.rows(c,"select id from "+CatalogSeed.identifier(e.get("table").toString())+" where id=?",e.get("id")).isEmpty(),"blocked rollback must not delete other created rows");
   boolean uncertain=false;try{CatalogSeed.reconcile(c,prepared);}catch(IllegalStateException e){uncertain=true;}check(uncertain,"reconcile must reject edited/missing snapshot");
   write(c,"update products set base_price=base_price-1 where id=?",productId);
   var rollback=CatalogSeed.rollback(c,removable,false);check(((List<?>)rollback.get("blocked")).isEmpty(),"new data should be rollbackable");
   var created=(List<Map<String,Object>>)removable.get("created");long variant=((Number)created.stream().filter(e->"product_variants".equals(e.get("table"))).findFirst().orElseThrow().get("id")).longValue();
   s.execute("create table external_references(id bigint primary key,variant_id bigint references product_variants(id))");
   write(c,"insert into external_references(id,variant_id) values(1,?)",variant);
   check(!((List<?>)CatalogSeed.rollback(c,removable,false).get("blocked")).isEmpty(),"external FK must block rollback");
   boolean blocked=false;try{CatalogSeed.rollback(c,removable,true);}catch(IllegalStateException e){blocked=true;}check(blocked,"unsafe rollback must reject all deletes");
   write(c,"delete from external_references where id=1");
   CatalogSeed.rollback(c,removable,true);c.commit();
   var preview=CatalogSeed.seed(c,m,false);check(((List<?>)preview.get("created")).size()==31,"preview should plan 31 catalog rows");c.rollback();
   var first=CatalogSeed.seed(c,m,true);check(((List<?>)first.get("created")).size()==31,"first apply should add exactly31 rows");c.commit();
   var again=CatalogSeed.seed(c,m,true);check(((List<?>)again.get("created")).isEmpty(),"second apply must add no rows");c.rollback();
   var row=c.createStatement().executeQuery("select count(*) from product_variants where stock_quantity is not null");row.next();check(row.getInt(1)==0,"unknown stock must stay NULL");
   row=c.createStatement().executeQuery("select count(*) from products where catalog_key like 'ref-20261028-%' and is_available=true");row.next();check(row.getInt(1)==0,"new products with unknown stock must remain unavailable");
   c.createStatement().executeUpdate("update products set base_price=base_price+1 where catalog_key='ref-20261028-mango-milk'");c.commit();
   var conflict=CatalogSeed.seed(c,m,true);check(!((List<?>)conflict.get("conflicts")).isEmpty(),"edited prices must be reported, not overwritten");check(((List<?>)conflict.get("created")).isEmpty(),"conflict rerun must not duplicate children");c.rollback();
   // Tampered manifest must fail before any insert.
   var bad=json.readValue(json.writeValueAsString(m),Map.class);((Map)((List<Map<String,Object>>)bad.get("operations")).getFirst()).put("table","orders");
   boolean rejected=false;try{CatalogSeed.seed(c,bad,true);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"transactional table must be rejected");c.rollback();
   System.out.println("CATALOG_SEED_SELF_TEST_PASS: preview, apply31, idempotency, stock/availability, conflict, whitelist, JSON ledger recovery, rollback edit and external-FK guards");
  }
 }
 static int write(Connection c,String sql,Object...args)throws Exception{return CatalogSeed.write(c,sql,args);}
 static void check(boolean pass,String message){if(!pass)throw new AssertionError(message);}
 static void insert(Connection c,String table,Map<String,Object> row)throws Exception{String sql="insert into "+table+"("+String.join(",",row.keySet())+") values("+String.join(",",Collections.nCopies(row.size(),"?"))+")";try(var p=c.prepareStatement(sql)){int n=1;for(Object x:row.values())p.setObject(n++,x);p.executeUpdate();}}
}
